/* ── Element spec ─────────────────────────────────────────────────────────
   source point (a)      → SphereGeometry(0.09)                gold  #E5A823
   upstream wavefronts   → LineSegments, circular arcs in XY at z=+2   #E5A823
   barrier (a)&(b)       → 3× PlaneGeometry quads #8C8C8C + 2 white slit quads
   downstream wavefronts → LineSegments, 2 arc families from the slits  #E5A823
   detection screen (a)  → PlaneGeometry 5×4 + CanvasTexture fringe pattern
   block arrows (b)      → BoxGeometry shaft + ConeGeometry head   #E0A500
   electron dots (b)     → THREE.Points with circular sprite       #E8A80C
   screens (b) ×3        → PlaneGeometry 4.2×3.4 #0D0D0D + Points cloud
   time arrow (b)        → CylinderGeometry shaft + ConeGeometry head, black
   all text              → addLabel (HTML overlay)
   ────────────────────────────────────────────────────────────────────────── */

const C = { gold: 0xE5A823, dot: 0xE8A80C, arrow: 0xE0A500, gray: 0x8C8C8C, black: 0x0D0D0D };
const XB = -4.0;          // barrier plane x
const XS = 5.0;           // panel (a) screen x
const LSCR = 9.0;         // barrier → screen distance L
const LAM = 0.08;         // de Broglie wavelength used for the fringe formula
const SLITW = 0.12;       // slit width (single-slit envelope)
const ARCZ = 2.0;         // depth plane the flat wavefront arcs are drawn in
let dSep = 1.0;           // slit separation

/* ── intensity  I(y) = cos²(π d y /(λL)) · sinc²(π a y /(λL)) ───────────── */
function intensity(y, d) {
  const k = Math.PI * y / (LAM * LSCR);
  const c = Math.cos(k * d);
  const s = k * SLITW;
  const env = Math.abs(s) < 1e-9 ? 1 : Math.sin(s) / s;
  return c * c * env * env;
}

/* inverse-CDF sampler (rebuilt whenever d changes; the SAME uniforms are
   reused so dots migrate into the new bands instead of reshuffling) */
let cdfY = null, cdfC = null;
function buildCDF(d, halfH) {
  const N = 1400;
  cdfY = new Float64Array(N); cdfC = new Float64Array(N);
  let acc = 0;
  for (let i = 0; i < N; i++) {
    const y = -halfH + 2 * halfH * i / (N - 1);
    acc += intensity(y, d) + 2e-3;
    cdfY[i] = y; cdfC[i] = acc;
  }
  for (let i = 0; i < N; i++) cdfC[i] /= acc;
}
function sampleY(u) {
  let lo = 0, hi = cdfC.length - 1;
  while (lo < hi) { const m = (lo + hi) >> 1; if (cdfC[m] < u) lo = m + 1; else hi = m; }
  return cdfY[lo];
}

/* ── shared helpers ──────────────────────────────────────────────────────── */
function quadYZ(color, extra = {}) {
  const g = new THREE.PlaneGeometry(1, 1); g.rotateY(Math.PI / 2);   // normal → +X
  return new THREE.Mesh(g, new THREE.MeshBasicMaterial(
    Object.assign({ color, side: THREE.DoubleSide }, extra)));
}
function setBand(mesh, y0, y1) {
  mesh.scale.y = Math.max(y1 - y0, 0.0005);
  mesh.position.y = (y0 + y1) / 2;
}

const panelA = new THREE.Group();
const panelB = new THREE.Group();
scene.add(panelA, panelB);

/* ── barrier with two white slits (three-quad construction) ─────────────── */
function makeBarrier() {
  const g = new THREE.Group(); g.position.x = XB;
  const H = 5.0, D = 4.0, t = 0.04;
  const top = quadYZ(C.gray), mid = quadYZ(C.gray), bot = quadYZ(C.gray);
  const s1 = quadYZ(0xffffff), s2 = quadYZ(0xffffff);
  [top, mid, bot, s1, s2].forEach(m => { m.scale.z = D; g.add(m); });
  s1.position.x = 0.005; s2.position.x = 0.005;
  g.userData.update = (d) => {
    setBand(top, d / 2 + t, H / 2);
    setBand(mid, -d / 2 + t, d / 2 - t);
    setBand(bot, -H / 2, -d / 2 - t);
    setBand(s1, d / 2 - t, d / 2 + t);
    setBand(s2, -d / 2 - t, -d / 2 + t);
  };
  g.userData.mid = mid;
  return g;
}
const barrierA = makeBarrier(); panelA.add(barrierA);
const barrierB = makeBarrier(); panelB.add(barrierB);

/* ── panel (a): source point + upstream wavefront arcs ──────────────────── */
const srcPt = new THREE.Mesh(new THREE.SphereGeometry(0.09, 16, 12),
  new THREE.MeshBasicMaterial({ color: C.gold }));
srcPt.position.set(-7.5, 0, ARCZ);
panelA.add(srcPt);

const arcMat = new THREE.LineBasicMaterial({
  color: C.gold, transparent: true, opacity: 0.8, depthWrite: false
});

function upstreamSegs() {
  const p = [], sx = -7.5, sy = 0;
  for (let r = 0.9; r <= 3.45; r += 0.22) {
    const n = Math.max(56, Math.round(r * 40));
    let px = 0, py = 0, pin = false;
    for (let i = 0; i <= n; i++) {
      const th = -1.42 + 2.84 * i / n;
      const x = sx + r * Math.cos(th), y = sy + r * Math.sin(th);
      const inside = (x <= XB - 0.05) && Math.abs(y) <= 2.3;
      if (inside && pin) p.push(px, py, ARCZ, x, y, ARCZ);
      px = x; py = y; pin = inside;
    }
  }
  return p;
}
const upLines = new THREE.LineSegments(
  new THREE.BufferGeometry().setAttribute('position',
    new THREE.BufferAttribute(new Float32Array(upstreamSegs()), 3)), arcMat);
panelA.add(upLines);

/* downstream: two arc families from the slits, clipped to a widening cone */
function downstreamSegs(d) {
  const p = [];
  const cone = (x) => Math.min(2.45, Math.max(d / 2 + 0.40,
    0.40 + (x - XB) / (XS - XB) * 2.10));
  for (const sy of [d / 2, -d / 2]) {
    for (let r = 0.16; r <= 9.4; r += 0.22) {
      const n = Math.min(150, Math.max(40, Math.round(r * 22)));
      let px = 0, py = 0, pin = false;
      for (let i = 0; i <= n; i++) {
        const th = -1.38 + 2.76 * i / n;
        const x = XB + r * Math.cos(th), y = sy + r * Math.sin(th);
        const inside = (x >= XB) && (x <= XS - 0.03) && Math.abs(y) <= cone(x);
        if (inside && pin) p.push(px, py, ARCZ, x, y, ARCZ);
        px = x; py = y; pin = inside;
      }
    }
  }
  return p;
}
const downLines = new THREE.LineSegments(new THREE.BufferGeometry(), arcMat);
downLines.frustumCulled = false;
panelA.add(downLines);
function rebuildDown() {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(downstreamSegs(dSep)), 3));
  g.computeBoundingBox(); g.computeBoundingSphere();
  downLines.geometry.dispose();
  downLines.geometry = g;
}

/* ── panel (a): detection screen with CanvasTexture fringes ─────────────── */
const fCanvas = document.createElement('canvas');
fCanvas.width = 4; fCanvas.height = 512;
const fCtx = fCanvas.getContext('2d');
const fTex = new THREE.CanvasTexture(fCanvas);
function updateFringe(d) {
  for (let j = 0; j < fCanvas.height; j++) {
    const y = (0.5 - j / (fCanvas.height - 1)) * 5.0;
    const I = Math.pow(Math.max(0, intensity(y, d)), 0.75);
    let r = 13 + (232 - 13) * I, g = 13 + (192 - 13) * I, b = 13 + (106 - 13) * I;
    if (I > 0.7) { const q = (I - 0.7) / 0.3; r += (255 - r) * q; g += (240 - g) * q; b += (192 - b) * q; }
    fCtx.fillStyle = `rgb(${r | 0},${g | 0},${b | 0})`;
    fCtx.fillRect(0, j, fCanvas.width, 1);
  }
  fTex.needsUpdate = true;
}
const screenA = quadYZ(0xffffff, { map: fTex });
screenA.scale.set(1, 5.0, 4.0); screenA.position.set(XS, 0, 0);
panelA.add(screenA);

/* ── panel (b): block arrows ─────────────────────────────────────────────── */
function blockArrow(y) {
  const g = new THREE.Group();
  const m = new THREE.MeshBasicMaterial({ color: C.arrow });
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(0.58, 0.32, 0.32), m);
  shaft.position.x = -6.5;
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.30, 0.40, 20), m);
  head.rotation.z = -Math.PI / 2; head.position.x = -6.0;
  g.add(shaft, head);
  g.position.set(0, y, 1.4);
  return g;
}
panelB.add(blockArrow(0.7), blockArrow(-0.7));

/* ── panel (b): free-flight electron dots ────────────────────────────────── */
function dotTexture() {
  const cv = document.createElement('canvas'); cv.width = cv.height = 64;
  const x = cv.getContext('2d');
  x.beginPath(); x.arc(32, 32, 28, 0, Math.PI * 2); x.fillStyle = '#fff'; x.fill();
  const t = new THREE.CanvasTexture(cv); return t;
}
const dotTex = dotTexture();
function dotMaterial(size) {
  return new THREE.PointsMaterial({
    color: C.dot, map: dotTex, size, sizeAttenuation: false,
    transparent: true, alphaTest: 0.4, depthWrite: false
  });
}
function cloud(list, size) {
  const arr = new Float32Array(list.length * 3);
  list.forEach((p, i) => { arr[3 * i] = p[0]; arr[3 * i + 1] = p[1]; arr[3 * i + 2] = p[2]; });
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  g.computeBoundingBox(); g.computeBoundingSphere();
  return new THREE.Points(g, dotMaterial(size));
}
const rnd = (a, b) => a + Math.random() * (b - a);
const upDots = [], dnDots = [];
for (let i = 0; i < 90; i++) upDots.push([rnd(-6.7, -4.02), rnd(-2.2, 2.2), rnd(-1.8, 1.9)]);
for (let i = 0; i < 46; i++) {
  const x = rnd(-3.9, 2.2);
  const h = 0.7 + (x + 4) / 6.2 * 1.9;
  dnDots.push([x, rnd(-h, h), rnd(-1.6, 1.7)]);
}
panelB.add(cloud(upDots, 6), cloud(dnDots, 6));

/* ── panel (b): three detection screens with accumulating hits ──────────── */
const SCR_X = [3.0, 5.6, 8.2], SCR_N = [30, 220, 1400], SCR_SZ = [6, 5.2, 4.2];
const screens = [];
SCR_X.forEach((x, k) => {
  const pl = quadYZ(C.black);
  pl.scale.set(1, 4.2, 3.4); pl.position.set(x, 0, 0);
  panelB.add(pl);

  const N = SCR_N[k];
  const u = new Float32Array(N), z = new Float32Array(N);
  for (let i = 0; i < N; i++) { u[i] = Math.random(); z[i] = (Math.random() * 2 - 1) * 1.6; }
  const pos = new Float32Array(N * 3);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const pts = new THREE.Points(geo, dotMaterial(SCR_SZ[k]));
  pts.frustumCulled = false;
  panelB.add(pts);

  screens.push({
    plane: pl, N,
    update() {
      for (let i = 0; i < N; i++) {
        pos[3 * i] = x + 0.04;
        pos[3 * i + 1] = THREE.MathUtils.clamp(sampleY(u[i]), -2.05, 2.05);
        pos[3 * i + 2] = z[i];
      }
      geo.attributes.position.needsUpdate = true;
      geo.computeBoundingBox(); geo.computeBoundingSphere();
    },
    setCount(c) { geo.setDrawRange(0, THREE.MathUtils.clamp(Math.round(c), 0, N)); }
  });
});

/* ── panel (b): time arrow ───────────────────────────────────────────────── */
{
  const m = new THREE.MeshBasicMaterial({ color: 0x1a1a1a });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 6.1, 10), m);
  shaft.rotation.z = -Math.PI / 2;
  shaft.position.set(5.65, -3.0, 0);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.36, 18), m);
  head.rotation.z = -Math.PI / 2;
  head.position.set(8.88, -3.0, 0);
  panelB.add(shaft, head);
}

/* ── apply the current slit separation everywhere ───────────────────────── */
let slitDirty = true;
function applySlit() {
  barrierA.userData.update(dSep);
  barrierB.userData.update(dSep);
  rebuildDown();
  updateFringe(dSep);
  buildCDF(dSep, 2.1);
  screens.forEach(s => s.update());
  document.getElementById('dVal').textContent = dSep.toFixed(2);
  document.getElementById('fringeInfo').textContent =
    'fringe spacing Δy = λL/d ≈ ' + (LAM * LSCR / dSep).toFixed(2) + ' units';
}
applySlit(); slitDirty = false;

/* ── camera (orthographic axonometric, auto-fit) ────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 10, z: 25 },
  heightFraction: 0.62
});

/* ── labels ──────────────────────────────────────────────────────────────── */
const labA = [
  addLabel('Electron<br>source', new THREE.Vector3(-8.9, 0.2, ARCZ), { fontSize: '15px' }),
  addLabel('(a)', new THREE.Vector3(-1.5, -3.6, 1.0), { fontSize: '15px' })
];
const labB = [
  addLabel('Electron<br>source', new THREE.Vector3(-9.0, 0.0, 1.4), { fontSize: '15px' }),
  addLabel('<b>Time</b>', new THREE.Vector3(5.7, -3.55, 0), { fontSize: '14px' }),
