const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

let model = 'a';
function setModel(m) {
  model = m;
  panelA.visible = (m === 'a');
  panelB.visible = (m === 'b');
  showLabs(labA, m === 'a');
  showLabs(labB, m === 'b');
  btnWave.classList.toggle('active', m === 'a');
  btnPart.classList.toggle('active', m === 'b');
}
btnWave.addEventListener('click', () => setModel('a'));
btnPart.addEventListener('click', () => setModel('b'));

slitSlider.addEventListener('input', () => {
  dSep = parseFloat(slitSlider.value);
