  g.add(plate);

  const strips = [];
  for (const side of [0.014, -0.014]) {
    for (let i = 0; i < 2; i++) {
      const s = quadYZ(0xffffff);
      s.scale.set(1, 0.075, DB * 0.68);
      s.position.x = side;
      s.userData.sign = i === 0 ? 1 : -1;
      g.add(s); strips.push(s);
    }
  }
  g.userData.update = (d) => { strips.forEach(s => { s.position.y = s.userData.sign * d / 2; }); };
  g.userData.plate = plate;
  return g;
}
const barrierA = makeBarrier(); panelA.add(barrierA);
const barrierB = makeBarrier(); panelB.add(barrierB);

/* ── panel (a): upstream wavefront arcs (dense, pressed against barrier) ── */
const arcMat = new THREE.LineBasicMaterial({
  color: C.gold, transparent: true, opacity: 0.85, depthWrite: false
});

function upstreamSegs() {
  const p = [];
  for (let r = 0.45; r <= 4.35; r += 0.145) {
    const n = Math.max(70, Math.min(260, Math.round(r * 60)));
    let px = 0, py = 0, pin = false;
    for (let i = 0; i <= n; i++) {
      const th = -1.47 + 2.94 * i / n;
      const x = SX + r * Math.cos(th), y = r * Math.sin(th);
      const inside = (x <= XB - 0.02) && Math.abs(y) <= 2.45;
      if (inside && pin) p.push(px, py, ARCZ, x, y, ARCZ);
      px = x; py = y; pin = inside;
    }
  }
  return p;
}
const upLines = new THREE.LineSegments(
  new THREE.BufferGeometry().setAttribute('position',
    new THREE.BufferAttribute(new Float32Array(upstreamSegs()), 3)), arcMat);
upLines.frustumCulled = false;
panelA.add(upLines);

/* ── panel (a): downstream arcs, fanning out to the FULL screen height ──── */
function downstreamSegs(d) {
  const p = [];
  const half = (x) => {
    const t = (x - XB) / (XS - XB);
    return Math.min(2.5, Math.max(d / 2 + 0.30, 0.30 + t * 2.30));
  };
  for (const sy of [d / 2, -d / 2]) {
    for (let r = 0.12; r <= 9.9; r += 0.20) {
      const n = Math.min(200, Math.max(48, Math.round(r * 26)));
      let px = 0, py = 0, pin = false;
      for (let i = 0; i <= n; i++) {
        const th = -1.44 + 2.88 * i / n;
        const x = XB + r * Math.cos(th), y = sy + r * Math.sin(th);
        const inside = (x >= XB) && (x <= XS - 0.03) && Math.abs(y) <= half(x);
        if (inside && pin) p.push(px, py, ARCZ, x, y, ARCZ);
        px = x; py = y; pin = inside;
      }
    }
  }
  return p;
}
const downLines = new THREE.LineSegments(new THREE.BufferGeometry(), arcMat);
downLines.frustumCulled = false;
panelA.add(downLines);
function rebuildDown() {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(downstreamSegs(dSep)), 3));
  g.computeBoundingBox(); g.computeBoundingSphere();
  downLines.geometry.dispose();
  downLines.geometry = g;
}

/* ── panel (a): detection screen — bright gold bands on near-black ──────── */
const fCanvas = document.createElement('canvas');
fCanvas.width = 8; fCanvas.height = 512;
const fCtx = fCanvas.getContext('2d');
const fTex = new THREE.CanvasTexture(fCanvas);
function updateFringe(d) {
  const H = fCanvas.height;
  for (let j = 0; j < H; j++) {
    const y = (0.5 - j / (H - 1)) * HB;
    const I = Math.max(0, Math.min(1, intensity(y, d)));      // linear — no gamma lift
    const r = 13 + I * (255 - 13);
    const g = 13 + I * (214 - 13);
    const b = 13 + I * (138 - 13);
    fCtx.fillStyle = `rgb(${r | 0},${g | 0},${b | 0})`;
    fCtx.fillRect(0, j, fCanvas.width, 1);
  }
  fTex.needsUpdate = true;
}
const screenA = quadYZ(0xffffff, { map: fTex });
screenA.scale.set(1, HB, DB);                 // same size as the barrier plate
screenA.position.set(XS, 0, 0);
panelA.add(screenA);

/* ── panel (b): block arrows ─────────────────────────────────────────────── */
function blockArrow(y) {
  const g = new THREE.Group();
  const m = new THREE.MeshBasicMaterial({ color: C.arrow });
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.34, 0.34), m);
  shaft.position.x = -6.5;
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.31, 0.42, 20), m);
  head.rotation.z = -Math.PI / 2; head.position.x = -5.98;
  g.add(shaft, head);
  g.position.set(0, y, 1.4);
  return g;
}
panelB.add(blockArrow(0.7), blockArrow(-0.7));

/* ── panel (b): free-flight electron dots ────────────────────────────────── */
function dotTexture() {
  const cv = document.createElement('canvas'); cv.width = cv.height = 64;
  const x = cv.getContext('2d');
  x.beginPath(); x.arc(32, 32, 28, 0, Math.PI * 2); x.fillStyle = '#fff'; x.fill();
  return new THREE.CanvasTexture(cv);
}
const dotTex = dotTexture();
function dotMaterial(size) {
  return new THREE.PointsMaterial({
    color: C.dot, map: dotTex, size, sizeAttenuation: false,
    transparent: true, alphaTest: 0.4, depthWrite: false
  });
}
function cloud(list, size) {
  const arr = new Float32Array(list.length * 3);
  list.forEach((p, i) => { arr[3 * i] = p[0]; arr[3 * i + 1] = p[1]; arr[3 * i + 2] = p[2]; });
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  g.computeBoundingBox(); g.computeBoundingSphere();
  return new THREE.Points(g, dotMaterial(size));
}
const rnd = (a, b) => a + Math.random() * (b - a);
const upDots = [], dnDots = [];
for (let i = 0; i < 90; i++) upDots.push([rnd(-6.6, -3.95), rnd(-2.2, 2.2), rnd(-1.8, 2.05)]);
for (let i = 0; i < 46; i++) {
  const x = rnd(-3.85, 2.1);
  const h = 0.7 + (x + 4) / 6.1 * 1.9;
  dnDots.push([x, rnd(-h, h), rnd(-1.6, 1.8)]);
}
panelB.add(cloud(upDots, 6), cloud(dnDots, 6));

/* ── panel (b): three detection screens with accumulating hits ──────────── */
const SCR_X = [3.0, 5.6, 8.2], SCR_N = [30, 220, 1400], SCR_SZ = [6, 5.2, 4.2];
const screens = [];
SCR_X.forEach((x, k) => {
  const pl = quadYZ(C.black);
  pl.scale.set(1, 4.2, 3.4); pl.position.set(x, 0, 0);
  panelB.add(pl);

  const N = SCR_N[k];
  const u = new Float32Array(N), z = new Float32Array(N);
  for (let i = 0; i < N; i++) { u[i] = Math.random(); z[i] = (Math.random() * 2 - 1) * 1.6; }
  const pos = new Float32Array(N * 3);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const pts = new THREE.Points(geo, dotMaterial(SCR_SZ[k]));
  pts.frustumCulled = false;
  panelB.add(pts);

  screens.push({
    plane: pl, N,
    update() {
      for (let i = 0; i < N; i++) {
        pos[3 * i] = x + 0.04;
        pos[3 * i + 1] = THREE.MathUtils.clamp(sampleY(u[i]), -2.05, 2.05);
        pos[3 * i + 2] = z[i];
      }
      geo.attributes.position.needsUpdate = true;
      geo.computeBoundingBox(); geo.computeBoundingSphere();
    },
    setCount(c) { geo.setDrawRange(0, THREE.MathUtils.clamp(Math.round(c), 0, N)); }
  });
});

/* ── panel (b): time arrow ───────────────────────────────────────────────── */
{
  const m = new THREE.MeshBasicMaterial({ color: 0x1a1a1a });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 6.1, 10), m);
  shaft.rotation.z = -Math.PI / 2;
  shaft.position.set(5.65, -3.0, 0);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.36, 18), m);
  head.rotation.z = -Math.PI / 2;
  head.position.set(8.88, -3.0, 0);
  panelB.add(shaft, head);
}

/* ── apply the current slit separation everywhere ───────────────────────── */
let slitDirty = true;
function applySlit() {
  barrierA.userData.update(dSep);
  barrierB.userData.update(dSep);
  rebuildDown();
  updateFringe(dSep);
  buildCDF(dSep, 2.1);
  screens.forEach(s => s.update());
  document.getElementById('dVal').textContent = dSep.toFixed(2);
  document.getElementById('fringeInfo').textContent =
    'fringe spacing Δy = λL/d ≈ ' + (LAM * LSCR / dSep).toFixed(2) + ' units';
}
applySlit(); slitDirty = false;

/* ── camera (orthographic axonometric, auto-fit) ────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 10, z: 25 },
  heightFraction: 0.62
});

/* ── labels ──────────────────────────────────────────────────────────────── */
const labA = [
  addLabel('Electron<br>source', new THREE.Vector3(-9.3, 0.2, ARCZ), { fontSize: '15px' }),
  addLabel('(a)', new THREE.Vector3(-1.0, -3.7, 1.0), { fontSize: '15px' })
];
const labB = [
  addLabel('Electron<br>source', new THREE.Vector3(-9.0, 0.0, 1.4), { fontSize: '15px' }),
  addLabel('<b>Time</b>', new THREE.Vector3(5.7, -3.55, 0), { fontSize: '14px' }),
  addLabel('(b)', new THREE.Vector3(0.4, -4.2, 0), { fontSize: '15px' })
];
function showLabs(list, on) { list.forEach(e => { e.div.style.visibility = on ? 'visible' : 'hidden'; }); }

/* ── hover / click explanations ─────────────────────────────────────────── */
registerInteractive(barrierA.userData.plate, {
  title: 'Double-slit barrier',
  tooltip: 'Opaque plate with two narrow slits',
  body: 'An opaque plate pierced by two narrow horizontal slits separated by d. Each slit acts as a new source of electron waves; downstream the two sets overlap and interfere.'
});
registerInteractive(screenA, {
  title: 'Interference fringes',
  tooltip: 'Bright/dark bands: I(y) = cos²(πdy/λL)',
  body: 'Where the two paths differ by a whole wavelength the waves add (bright gold band); where they differ by half a wavelength they cancel (black band). Spacing Δy ≈ λL/d.'
});
registerInteractive(screens[2].plane, {
  title: 'Accumulated detections',
  tooltip: 'Thousands of single hits',
  body: 'Every electron is detected as one localized dot — a particle. Only after thousands of detections do the dots pile up into exactly the wave interference pattern of panel (a).'
});

/* ── UI wiring ───────────────────────────────────────────────────────────── */
document.getElementById('btnReset').style.display = '';

const btnWave = document.getElementById('btnWave');
const btnPart = document.getElementById('btnPart');
const btnPlay = document.getElementById('btnPlay');
const progSlider = document.getElementById('progSlider');
const slitSlider = document.getElementById('slitSlider');
const countInfo = document.getElementById('countInfo');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

let model = 'a';
function setModel(m) {
  model = m;
  panelA.visible = (m === 'a');
  panelB.visible = (m === 'b');
  showLabs(labA, m === 'a');
  showLabs(labB, m === 'b');
  btnWave.classList.toggle('active', m === 'a');
  btnPart.classList.toggle('active', m === 'b');
}
btnWave.addEventListener('click', () => setModel('a'));
btnPart.addEventListener('click', () => setModel('b'));

slitSlider.addEventListener('input', () => {
  dSep = parseFloat(slitSlider.value);
  tween = null;
  slitDirty = true;
});

/* time-lapse accumulation */
let playing = false, prog = 1, holdUntil = 0;
const stage = (p, a, b) => THREE.MathUtils.clamp((p - a) / (b - a), 0, 1);
function applyProgress(p) {
  const c0 = SCR_N[0] * stage(p, 0.00, 0.28);
  const c1 = SCR_N[1] * stage(p, 0.12, 0.62);
  const c2 = SCR_N[2] * stage(p, 0.35, 1.00);
  screens[0].setCount(c0); screens[1].setCount(c1); screens[2].setCount(c2);
  countInfo.textContent = 'hits: ' + Math.round(c0) + ' / ' + Math.round(c1) + ' / ' + Math.round(c2);
}
applyProgress(1);

btnPlay.addEventListener('click', () => {
  playing = !playing;
  if (playing) {
    if (model !== 'b') setModel('b');
    if (prog >= 1) prog = 0;
    holdUntil = 0;
    btnPlay.textContent = '❚❚ Pause';
    btnPlay.classList.add('active');
  } else {
    btnPlay.textContent = '▶ Play time-lapse';
    btnPlay.classList.remove('active');
  }
});
progSlider.addEventListener('input', () => {
  prog = parseFloat(progSlider.value);
  playing = false; holdUntil = 0;
  btnPlay.textContent = '▶ Play time-lapse';
  btnPlay.classList.remove('active');
  applyProgress(prog);
});

/* guided demo steps */
const STEPS = [
  {
    t: 'Waves through two slits',
    n: 'Golden wavefronts spread from the source, pass through both slits and overlap. Where crest meets crest the screen is bright gold; where crest meets trough it stays black — horizontal fringes.',
    m: 'a', d: 1.0, play: false
  },
  {
    t: "Widen the slits' separation",
    n: 'Pushing the slits farther apart squeezes the fringes together; bringing them closer spreads them out — Δy ≈ λL/d.',
    m: 'a', d: 1.8, play: false
  },
  {
    t: 'One electron at a time',
    n: 'Switch to the particle picture: electrons arrive as individual dots. The first screen is a sparse, seemingly random scatter — no pattern at all.',
    m: 'b', d: 1.0, play: false, prog: 0.25
  },
  {
    t: 'The pattern emerges',
    n: 'Let detections accumulate. With hundreds and then thousands of hits the dots pile up exactly into the fringes of panel (a) — particle detections, wave statistics.',
    m: 'b', d: 1.0, play: true
  }
];
let stepIdx = 0;
let tween = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '. ' + s.t;
  stepText.textContent = s.n;
  setModel(s.m);
  tween = { from: dSep, to: s.d, t0: performance.now(), dur: 800 };
  if (s.play) {
    prog = 0; playing = true; holdUntil = 0;
    btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  } else {
    playing = false; holdUntil = 0;
    btnPlay.textContent = '▶ Play time-lapse'; btnPlay.classList.remove('active');
    prog = (s.prog !== undefined) ? s.prog : 1;
    progSlider.value = prog;
    applyProgress(prog);
  }
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── state loop (geometry updates only; the scaffold renders) ───────────── */
let lastT = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, (now - lastT) / 1000); lastT = now;

  if (tween) {
    const k = THREE.MathUtils.clamp((now - tween.t0) / tween.dur, 0, 1);
    const e = k * k * (3 - 2 * k);
    dSep = tween.from + (tween.to - tween.from) * e;
    slitSlider.value = dSep.toFixed(2);
    slitDirty = true;
    if (k >= 1) tween = null;
  }
  if (slitDirty) { applySlit(); slitDirty = false; }

  if (playing) {
    if (holdUntil) {
      if (now >= holdUntil) { holdUntil = 0; prog = 0; }
    } else {
      prog += dt * 0.22;
      if (prog >= 1) { prog = 1; holdUntil = now + 1500; }
      progSlider.value = prog;
      applyProgress(prog);
    }
  }
}
requestAnimationFrame(tick);

/* initial state */
setModel('a');
goToStep(0);
// @FIGURE_CODE_END

