    }
  },
  {
    "title": "One electron at a time",
    "narration": "Switch to the particle picture: electrons arrive as individual dots. The first screen is just a sparse, seemingly random scatter — no pattern at all.",
    "state": {
      "modelToggle": "(b) Particle accumulation",
      "slitSeparation": 1
    }
  },
  {
    "title": "The pattern emerges",
