/* ── Element spec (one line per element) ──────────────────────────────────
   barrier (a)&(b)       → ONE continuous PlaneGeometry plate 5×4, #8C8C8C
   slits                 → 2 thin white PlaneGeometry strips, depthTest:false,
                           renderOrder 5 → always readable over the arcs
   upstream wavefronts   → LineSegments, DENSE circular arcs in XY at z=ARCZ #E5A823
   downstream wavefronts → LineSegments, 2 dense arc families from the slits,
                           clipped to a cone that fans to the FULL screen height
   detection screen (a)  → PlaneGeometry 5×4 + CanvasTexture: NARROW gold bands
                           on near-black (gamma-sharpened I(y))
   block arrows (b)      → BoxGeometry shaft + ConeGeometry head   #E0A500
   electron dots (b)     → THREE.Points, circular sprite           #E8A80C
   screens (b) ×3        → PlaneGeometry 4.2×3.4 #0D0D0D + Points clouds
   time arrow (b)        → CylinderGeometry shaft + ConeGeometry head, black
   all text              → addLabel (HTML overlay)
   ────────────────────────────────────────────────────────────────────────── */

const C = { gold: 0xE5A823, dot: 0xE8A80C, arrow: 0xE0A500, gray: 0x8C8C8C, black: 0x0D0D0D };
const SX = -8.0;           // source x
const XB = -4.5;           // barrier plane x
const XS = 7.0;            // panel (a) screen x  (long propagation gap, as in source)
const LSCR = XS - XB;      // barrier → screen distance L = 11.5
const LAM = 0.062;         // effective wavelength → Δy = λL/d ≈ 0.71 at d = 1
const SLITW = 0.10;        // slit width (single-slit envelope)
const ARCZ = 2.06;         // depth plane in which the flat wavefront arcs live
const HB = 5.0, DB = 4.0;  // barrier / screen (a) height and depth
let dSep = 1.0;            // slit separation

/* ── intensity  I(y) = cos²(π d y /(λL)) · sinc²(π a y /(λL)) ───────────── */
function intensity(y, d) {
  const k = Math.PI * y / (LAM * LSCR);
  const c = Math.cos(k * d);
  const s = k * SLITW;
  const env = Math.abs(s) < 1e-9 ? 1 : Math.sin(s) / s;
  return c * c * env * env;
}

/* inverse-CDF sampler — the SAME uniforms are reused when d changes so dots
   migrate into the new bands instead of reshuffling */
let cdfY = null, cdfC = null;
function buildCDF(d, halfH) {
  const N = 1400;
  cdfY = new Float64Array(N); cdfC = new Float64Array(N);
  let acc = 0;
  for (let i = 0; i < N; i++) {
    const y = -halfH + 2 * halfH * i / (N - 1);
    acc += intensity(y, d) + 2e-3;
    cdfY[i] = y; cdfC[i] = acc;
  }
  for (let i = 0; i < N; i++) cdfC[i] /= acc;
}
function sampleY(u) {
  let lo = 0, hi = cdfC.length - 1;
  while (lo < hi) { const m = (lo + hi) >> 1; if (cdfC[m] < u) lo = m + 1; else hi = m; }
  return cdfY[lo];
}

/* ── helpers ─────────────────────────────────────────────────────────────── */
function quadYZ(color, extra = {}) {
  const g = new THREE.PlaneGeometry(1, 1); g.rotateY(Math.PI / 2);   // normal → +X
  return new THREE.Mesh(g, new THREE.MeshBasicMaterial(
    Object.assign({ color, side: THREE.DoubleSide }, extra)));
}

const panelA = new THREE.Group();
const panelB = new THREE.Group();
scene.add(panelA, panelB);

/* ── barrier: ONE continuous gray plate, white slit strips ON TOP ───────── */
function makeBarrier() {
  const g = new THREE.Group(); g.position.x = XB;
  const plate = quadYZ(C.gray);
  plate.scale.set(1, HB, DB);
  plate.renderOrder = 0;
  g.add(plate);

  const strips = [];
  for (let i = 0; i < 2; i++) {
    // depthTest:false + high renderOrder ⇒ the slits stay legible even where the
    // wavefront arcs (drawn in a plane just in front of the plate) cross them.
    const s = quadYZ(0xffffff, { depthTest: false, depthWrite: false });
    s.scale.set(1, 0.085, DB * 0.66);
    s.position.x = 0.05;               // nudged toward the viewer side
    s.renderOrder = 5;
    s.userData.sign = i === 0 ? 1 : -1;
    g.add(s); strips.push(s);
  }
  g.userData.update = (d) => { strips.forEach(s => { s.position.y = s.userData.sign * d / 2; }); };
  g.userData.plate = plate;
  return g;
}
const barrierA = makeBarrier(); panelA.add(barrierA);
const barrierB = makeBarrier(); panelB.add(barrierB);

/* ── panel (a): upstream wavefront arcs (dense, pressed against barrier) ── */
const arcMatUp = new THREE.LineBasicMaterial({
  color: C.gold, transparent: true, opacity: 0.92, depthWrite: false
});
const arcMatDn = new THREE.LineBasicMaterial({
  color: C.gold, transparent: true, opacity: 0.8, depthWrite: false
});

function upstreamSegs() {
  const p = [];
  for (let r = 0.40; r <= 4.70; r += 0.105) {     // dense radial step
    const n = Math.max(80, Math.min(300, Math.round(r * 70)));
    let px = 0, py = 0, pin = false;
    for (let i = 0; i <= n; i++) {
      const th = -1.48 + 2.96 * i / n;
      const x = SX + r * Math.cos(th), y = r * Math.sin(th);
      const inside = (x <= XB - 0.01) && Math.abs(y) <= 2.45;
      if (inside && pin) p.push(px, py, ARCZ, x, y, ARCZ);
      px = x; py = y; pin = inside;
    }
  }
  return p;
}
const upLines = new THREE.LineSegments(
  new THREE.BufferGeometry().setAttribute('position',
    new THREE.BufferAttribute(new Float32Array(upstreamSegs()), 3)), arcMatUp);
upLines.frustumCulled = false;
upLines.renderOrder = 1;
panelA.add(upLines);

/* ── panel (a): downstream arcs, fanning out to the FULL screen height ──── */
function downstreamSegs(d) {
  const p = [];
  const half = (x) => {
    const t = THREE.MathUtils.clamp((x - XB) / (XS - XB), 0, 1);
    return Math.min(2.48, Math.max(d / 2 + 0.28, 0.28 + t * 2.22));
  };
  for (const sy of [d / 2, -d / 2]) {
    for (let r = 0.10; r <= 12.2; r += 0.145) {   // dense radial step
      const n = Math.min(260, Math.max(56, Math.round(r * 30)));
      let px = 0, py = 0, pin = false;
      for (let i = 0; i <= n; i++) {
        const th = -1.45 + 2.90 * i / n;
        const x = XB + r * Math.cos(th), y = sy + r * Math.sin(th);
        const inside = (x >= XB) && (x <= XS - 0.03) && Math.abs(y) <= half(x);
        if (inside && pin) p.push(px, py, ARCZ, x, y, ARCZ);
        px = x; py = y; pin = inside;
      }
    }
  }
  return p;
}
const downLines = new THREE.LineSegments(new THREE.BufferGeometry(), arcMatDn);
downLines.frustumCulled = false;
downLines.renderOrder = 1;
panelA.add(downLines);
function rebuildDown() {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(downstreamSegs(dSep)), 3));
  g.computeBoundingBox(); g.computeBoundingSphere();
  downLines.geometry.dispose();
  downLines.geometry = g;
}

/* ── panel (a): detection screen — NARROW gold bands on near-black ─────── */
const fCanvas = document.createElement('canvas');
fCanvas.width = 8; fCanvas.height = 1024;
const fCtx = fCanvas.getContext('2d');
const fTex = new THREE.CanvasTexture(fCanvas);
fTex.minFilter = THREE.LinearFilter;
function updateFringe(d) {
  const H = fCanvas.height;
  for (let j = 0; j < H; j++) {
    const y = (0.5 - j / (H - 1)) * HB;
    let I = Math.max(0, Math.min(1, intensity(y, d)));
    I = Math.pow(I, 2.1);                       // gamma ⇒ thin bright lines, black gaps
    const r = 10 + I * (255 - 10);
    const g = 10 + I * (240 - 10);
    const b = 10 + I * (182 - 10);
    fCtx.fillStyle = `rgb(${r | 0},${g | 0},${b | 0})`;
    fCtx.fillRect(0, j, fCanvas.width, 1);
  }
  fTex.needsUpdate = true;
}
const screenA = quadYZ(0xffffff, { map: fTex });
screenA.scale.set(1, HB, DB);                 // same size as the barrier plate
screenA.position.set(XS, 0, 0);
panelA.add(screenA);

/* ── panel (b): block arrows ─────────────────────────────────────────────── */
function blockArrow(y) {
  const g = new THREE.Group();
  const m = new THREE.MeshBasicMaterial({ color: C.arrow });
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.34, 0.34), m);
  shaft.position.x = -7.0;
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.31, 0.42, 20), m);
  head.rotation.z = -Math.PI / 2; head.position.x = -6.48;
